523	// Shared drain tail: capture the (pre-execution) state, report `resume_pc`
524	// as the vsim resume point, and exit 200.
525	static void handoff_drain(unsigned int vcpu_idx, uint64_t resume_pc)
526	{
527	    drain_state_to_file(vcpu_idx, resume_pc, 0, outfile_path);
528	    // 200 == kExitHandoffToQemu in verilator/src/hybrid/exit_codes.hpp.
529	    // Distinguishes drain from workload completion (0) so the orchestrator
530	    // can decide the next spawn.
531	    exit(200);
